#!/usr/bin/env python3
"""Materialize the exact, published Monitoring, Chemistry and field-selection and assignment 92 source bank without network access.

This file is a transport only. It does not install into an application, import
science, change a Workspace, or replace newer source. After materialization,
follow the retained README and run the original stage.py and guarded installer.
Source bank: public-commons-sprint-2026 @ 8869efd5092de7b89b71db16d3fba60fabcc6729
Directory: deliverables/eco13-chemistry-compound-upgrade-20261013

Original receiving commands, with BANK/STAGE outside APP and Workspace:
    python -B MATERIALIZER --bank BANK
    python -B BANK/stage.py --application APP --source-root STAGE
    python -B STAGE/operator/install_chemistry.py --application APP --source-root STAGE --dry-run
    python -B STAGE/operator/install_chemistry.py --application APP --source-root STAGE
Then follow STAGE/source/monitoring-field-study/INSTALLATION.md to receive the
original populated field selection, operate its maintained working desk, and use
STAGE/source/monitoring-chemistry-study/README.md for complete editable receiving.
Preserve current accepted processes until their normal source-change boundary.
"""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import tempfile

PAYLOAD_SHA256 = "749bb0a1893bb907853b1bce038631bb47e4ea816b5158d084699e975dc3a34e"
PAYLOAD_BYTES = 2568213
SOURCE_COMMIT = "8869efd5092de7b89b71db16d3fba60fabcc6729"


def materialize(bank: Path) -> dict:
    body = gzip.decompress(base64.b64decode(PAYLOAD, validate=False))
    if len(body) != PAYLOAD_BYTES or hashlib.sha256(body).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("The complete source-bank transport identity does not match.")
    document = json.loads(body)
    if document.get("schema") != "upstate.bank-materialization/v1" or document.get("source_commit") != SOURCE_COMMIT:
        raise ValueError("This is not the pinned Monitoring and Chemistry source bank.")
    files = document["files"]
    if len(files) != 14:
        raise ValueError("The original complete bank requires fourteen files.")
    bank = bank.expanduser().absolute()
    if any(part.is_symlink() for part in (bank, *bank.parents)):
        raise ValueError("Choose a bank directory without symbolic-link ancestors.")
    staged = []
    seen = set()
    for entry in files:
        name = entry["path"]
        relative = PurePosixPath(name)
        if relative.is_absolute() or ".." in relative.parts or name in seen:
            raise ValueError("Unsafe or repeated bank member: " + name)
        seen.add(name)
        value = entry["content"].encode("utf-8")
        if len(value) != entry["bytes"] or hashlib.sha256(value).hexdigest() != entry["sha256"]:
            raise ValueError("Source member identity mismatch: " + name)
        target = bank.joinpath(*relative.parts)
        if any(part.is_symlink() for part in (target, *target.parents)):
            raise ValueError("Source member has a symbolic-link ancestor: " + name)
        if target.exists() and (not target.is_file() or target.read_bytes() != value):
            raise ValueError("Preserved a differing existing bank file: " + str(target))
        staged.append((target, value, entry))
    bank.mkdir(parents=True, exist_ok=True)
    for target, value, entry in staged:
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            if target.read_bytes() != value:
                raise ValueError("Bank file changed during materialization: " + str(target))
            continue
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(dir=target.parent, prefix=".materialize-", delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(value)
                stream.flush()
                os.fsync(stream.fileno())
            try:
                os.link(temporary, target)
            except FileExistsError:
                if target.is_symlink() or not target.is_file() or target.read_bytes() != value:
                    raise ValueError("Bank file changed during materialization: " + str(target))
        finally:
            if temporary is not None:
                temporary.unlink(missing_ok=True)
    for target, value, entry in staged:
        if target.is_symlink() or target.read_bytes() != value:
            raise ValueError("Written member did not reopen exactly: " + entry["path"])
    return {
        "schema": "upstate.bank-materialization-receipt/v1",
        "source_commit": SOURCE_COMMIT,
        "bank": str(bank),
        "members": len(staged),
        "member_bytes": sum(len(value) for _, value, _ in staged),
        "payload_sha256": PAYLOAD_SHA256,
        "next": "Read README.md; run the original stage.py and operator/install_chemistry.py against a separate original application copy.",
    }


